using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.EventSystems;using Bokumyaku.Presentation;
public static class HudSizeCheck{
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");Canvas.ForceUpdateCanvases();var rows=new List<object>();foreach(var name in new[]{"Speed","Auto","Save","Home","ReducedMotion","Upgrade0","Upgrade1","Upgrade2","Upgrade3","Upgrade4"}){var b=GameObject.Find(name).GetComponent<UnityEngine.UI.Button>();var r=(RectTransform)b.transform;var c=new Vector3[4];r.GetWorldCorners(c);float width=c[2].x-c[0].x,height=c[2].y-c[0].y;var d=new PointerEventData(EventSystem.current){position=(c[0]+c[2])*.5f};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);bool reachable=hits.Count>0&&hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Button>()==b;if(width<44||height<44||!reachable)throw new Exception(name+" target too small or blocked: "+width+","+height);rows.Add(new{name,width,height,reachable});}var result=new{passed=true,screen=new{Screen.width,Screen.height},viewportHeight=BokumyakuBattleHud.GetBattleViewport().height,buttons=rows};File.WriteAllText(Path.GetFullPath("../docs/evidence/hud-size-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/hud-size-check.png"));return result;}}

